// parquet_reader.js
/* Placeholder ParquetReader service for Node.js */
// Uses the "parquetjs" package to read Parquet files generated by export_to_parquet.py

const parquet = require('parquetjs');
const path = require('path');

async function readParquet(tableName) {
  const filePath = path.join(__dirname, '..', 'data', 'parquet', `${tableName}.parquet`);
  try {
    const reader = await parquet.ParquetReader.openFile(filePath);
    const cursor = reader.getCursor();
    const rows = [];
    let record = null;
    while (record = await cursor.next()) {
      rows.push(record);
    }
    await reader.close();
    return rows;
  } catch (err) {
    console.error(`Failed to read ${filePath}:`, err);
    return [];
  }
}

// Example usage: node parquet_reader.js users
if (require.main === module) {
  const table = process.argv[2] || 'users';
  readParquet(table).then(rows => {
    console.log(`Rows from ${table}:`, rows);
  });
}
